/**
 * Refund service.
 *
 * Handles refunding orders. A refund is only allowed if the order exists,
 * has not already been refunded, and the total is at least 10.
 */

import { lookupOrder, markOrderRefunded } from './order.service';
import { Result, ok, err } from '../kernel/result';
import { AppError, missingResource } from '../kernel/errors';

export function refundOrder(orderId: string): Result<void, AppError> {
  const order = lookupOrder(orderId);

  if (order === undefined) {
    return err(missingResource(`order ${orderId}`));
  }

  if (order.refunded) {
    return err({
      code: 'ALREADY_REFUNDED',
      message: `Order ${orderId} has already been refunded`,
    });
  }

  if (order.total < 10) {
    return err({
      code: 'REFUND_INVALID_AMOUNT',
      message: `Order ${orderId} total (${order.total}) must be at least 10 to refund`,
    });
  }

  markOrderRefunded(order);
  return ok(undefined);
}

